INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_HARRANIAN','Harranian Sabian Star-Religion',200,1000)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_GREEN_MOON_GOD','secondary scholarship','Tamara M. Green, The City of the Moon God: Religious Traditions of Harran','Primary scholarly study of the Harranian Sabian planetary cult, its temples, deities, and Hermetic-philosophical milieu from late antiquity through the Abbasid period.')
INSERT INTO _e VALUES
 ('ENT_HRN_PLANETARY_SEVEN','The Seven Planetary Deities of Harran (al-Aṣnām al-Sabʿa)','collective','pantheon-hub','Sabian/Harranian','astral cosmology','B','Collective hub for the seven planetary gods venerated by the Harranian Sabians, each with its own temple and planetary metal/color/day; attested in Ibn al-Nadim''s Fihrist and analyzed in Green, City of the Moon God.'),
 ('ENT_HRN_SHAMASH_SUN','Shamash (the Sun) of Harran','deity','planetary deity','Sabian/Harranian','sun, sovereignty','B','The Sun-deity of the Harranian heptad, continuing Mesopotamian Shamash and identified with Helios; attested via Ibn al-Nadim and analyzed in Green.'),
 ('ENT_HRN_SIN_MOON','Sin (the Moon) of Harran [Sabian cult-phase]','deity','planetary deity','Sabian/Harranian','moon, chief deity','B','The Moon-god, supreme deity of Harran whose great temple (E-hulhul) defined the city''s identity; the Sabian planetary continuation of the older Aramean/Mesopotamian Sin. Wired to the existing ENT_ARA_SIN_HARRAN and ENT_MES_NANNA_SIN rather than duplicating them.'),
 ('ENT_HRN_KRONOS_SATURN','Kronos (Saturn) of Harran','deity','planetary deity','Sabian/Harranian','Saturn, time, ill-fortune','B','Saturn-deity of the heptad, identified with Greek Kronos and Mesopotamian Ninurta/Ninib; black-clad rites attested in the Fihrist and Green.'),
 ('ENT_HRN_ZEUS_JUPITER','Zeus (Jupiter / Bel) of Harran','deity','planetary deity','Sabian/Harranian','Jupiter, kingship of heaven','B','Jupiter-deity, identified with Zeus/Bel-Marduk; benefic planet of the heptad per Ibn al-Nadim and Green.'),
 ('ENT_HRN_ARES_MARS','Ares (Mars / Nergal) of Harran','deity','planetary deity','Sabian/Harranian','Mars, war, ill-fortune','B','Mars-deity of the heptad, identified with Greek Ares and Mesopotamian Nergal; malefic planet with red-tinged blood rites described in the Fihrist and Green.'),
 ('ENT_HRN_APHRODITE_VENUS','Aphrodite (Venus / Ishtar) of Harran','deity','planetary deity','Sabian/Harranian','Venus, love, fortune','B','Venus-deity of the heptad, the planet al-Zuhra, identified with Greek Aphrodite and Mesopotamian Ishtar; lesser benefic per the Fihrist and Green.'),
 ('ENT_HRN_HERMES_MERCURY','Hermes-Nabu (Mercury) of Harran','deity','planetary deity','Sabian/Harranian','Mercury, scribal wisdom','B','Mercury-deity of the heptad, identified with Greek Hermes and Mesopotamian Nabu; in Harranian thought the planetary Mercury blurs into the prophet-sage Hermes Trismegistus. Distinct entity from the prophet-sage ENT_HRN_HERMES_TRISMEGISTUS below.'),
 ('ENT_HRN_HERMES_TRISMEGISTUS','Hermes Trismegistus (=Idris) as Harranian Prophet-Sage','figure','prophet-sage','Sabian/Harranian','revealed wisdom, prophecy','B','The Harranian Sabians claimed Hermes (identified with Qur''anic Idris/Enoch) as their prophet and Hermetic writings as scripture, a claim that legitimized them under Islam; documented by Ibn al-Nadim and analyzed in Green. Wired by reception_of to existing ENT_HER_TRISMEGISTUS and equated_with ENT_ISL_IDRIS.'),
 ('ENT_HRN_AGATHODAIMON','Agathodaimon as Harranian Prophet-Sage','figure','prophet-sage','Sabian/Harranian','revealed wisdom','C','Agathodaimon (''Good Spirit''), paired with Hermes in Hermetic literature, is named alongside Hermes as a prophet/teacher of the Harranian Sabians in the Fihrist tradition; lesser-attested than Hermes. Same figure as the existing pan-Hermetic ENT_LAT_AGATHOS_DAIMON_HERMETIC (''Agathos Daimon''), to which this Harranian-reception entity is wired (homonym/reception, not a duplicate).'),
 ('ENT_HRN_PLANETARY_ASCENT','The Planetary Ascent of the Soul (Harranian)','doctrine','doctrine','Sabian/Harranian','soteriology, cosmology','C','Hermetic-derived Harranian doctrine that the purified soul ascends through the seven planetary spheres, shedding each planet''s qualities, to return to its celestial origin; the conceptual link between the planetary cult and Hermetic philosophy per Green and the Corpus Hermeticum (esp. CH I, Poimandres).'),
 ('ENT_HRN_TEMPLES','The Planetary Temples of Harran (Buyut al-Kawakib)','collective','cult-site collective','Sabian/Harranian','sacred architecture','C','The set of temples assigned to each planet, reportedly built in distinctive geometric forms (e.g. the round/square/triangular houses) keyed to each planet, described in the Fihrist and Picatrix-related traditions and analyzed in Green.');
