INSERT INTO _p VALUES
 ('ENT_HRN_PLANETARY_SEVEN','PER_HARRANIAN','Collective hub for the seven planetary gods venerated by the Harranian Sabians, each with its own temple and planetary metal/color/day; attested in Ibn al-Nadim''s Fihrist and analyzed in Green, City of the Moon God.'),
 ('ENT_HRN_SHAMASH_SUN','PER_HARRANIAN','The Sun-deity of the Harranian heptad, continuing Mesopotamian Shamash and identified with Helios; attested via Ibn al-Nadim and analyzed in Green.'),
 ('ENT_HRN_SIN_MOON','PER_HARRANIAN','The Moon-god, supreme deity of Harran whose great temple (E-hulhul) defined the city''s identity; the Sabian planetary continuation of the older Aramean/Mesopotamian Sin. Wired to the existing ENT_ARA_SIN_HARRAN and ENT_MES_NANNA_SIN rather than duplicating them.'),
 ('ENT_HRN_KRONOS_SATURN','PER_HARRANIAN','Saturn-deity of the heptad, identified with Greek Kronos and Mesopotamian Ninurta/Ninib; black-clad rites attested in the Fihrist and Green.'),
 ('ENT_HRN_ZEUS_JUPITER','PER_HARRANIAN','Jupiter-deity, identified with Zeus/Bel-Marduk; benefic planet of the heptad per Ibn al-Nadim and Green.'),
 ('ENT_HRN_ARES_MARS','PER_HARRANIAN','Mars-deity of the heptad, identified with Greek Ares and Mesopotamian Nergal; malefic planet with red-tinged blood rites described in the Fihrist and Green.'),
 ('ENT_HRN_APHRODITE_VENUS','PER_HARRANIAN','Venus-deity of the heptad, the planet al-Zuhra, identified with Greek Aphrodite and Mesopotamian Ishtar; lesser benefic per the Fihrist and Green.'),
 ('ENT_HRN_HERMES_MERCURY','PER_HARRANIAN','Mercury-deity of the heptad, identified with Greek Hermes and Mesopotamian Nabu; in Harranian thought the planetary Mercury blurs into the prophet-sage Hermes Trismegistus. Distinct entity from the prophet-sage ENT_HRN_HERMES_TRISMEGISTUS below.'),
 ('ENT_HRN_HERMES_TRISMEGISTUS','PER_HARRANIAN','The Harranian Sabians claimed Hermes (identified with Qur''anic Idris/Enoch) as their prophet and Hermetic writings as scripture, a claim that legitimized them under Islam; documented by Ibn al-Nadim and analyzed in Green. Wired by reception_of to existing ENT_HER_TRISMEGISTUS and equated_with ENT_ISL_IDRIS.'),
 ('ENT_HRN_AGATHODAIMON','PER_HARRANIAN','Agathodaimon (''Good Spirit''), paired with Hermes in Hermetic literature, is named alongside Hermes as a prophet/teacher of the Harranian Sabians in the Fihrist tradition; lesser-attested than Hermes. Same figure as the existing pan-Hermetic ENT_LAT_AGATHOS_DAIMON_HERMETIC (''Agathos Daimon''), to which this Harranian-reception entity is wired (homonym/reception, not a duplicate).'),
 ('ENT_HRN_PLANETARY_ASCENT','PER_HARRANIAN','Hermetic-derived Harranian doctrine that the purified soul ascends through the seven planetary spheres, shedding each planet''s qualities, to return to its celestial origin; the conceptual link between the planetary cult and Hermetic philosophy per Green and the Corpus Hermeticum (esp. CH I, Poimandres).'),
 ('ENT_HRN_TEMPLES','PER_HARRANIAN','The set of temples assigned to each planet, reportedly built in distinctive geometric forms (e.g. the round/square/triangular houses) keyed to each planet, described in the Fihrist and Picatrix-related traditions and analyzed in Green.');
