INSERT INTO _r VALUES
 ('ENT_HRN_SHAMASH_SUN','member_of','ENT_HRN_PLANETARY_SEVEN','high','Shamash/Sun is one of the seven planetary deities of the Harranian heptad (Green; Fihrist).'),
 ('ENT_HRN_SIN_MOON','member_of','ENT_HRN_PLANETARY_SEVEN','high','Sin/Moon is the supreme member of the Harranian planetary heptad (Green).'),
 ('ENT_HRN_KRONOS_SATURN','member_of','ENT_HRN_PLANETARY_SEVEN','high','Kronos/Saturn is one of the seven planetary deities of Harran (Green; Fihrist).'),
 ('ENT_HRN_ZEUS_JUPITER','member_of','ENT_HRN_PLANETARY_SEVEN','high','Zeus/Jupiter is one of the seven planetary deities of Harran (Green; Fihrist).'),
 ('ENT_HRN_ARES_MARS','member_of','ENT_HRN_PLANETARY_SEVEN','high','Ares/Mars is one of the seven planetary deities of Harran (Green; Fihrist).'),
 ('ENT_HRN_APHRODITE_VENUS','member_of','ENT_HRN_PLANETARY_SEVEN','high','Aphrodite/Venus is one of the seven planetary deities of Harran (Green; Fihrist).'),
 ('ENT_HRN_HERMES_MERCURY','member_of','ENT_HRN_PLANETARY_SEVEN','high','Hermes-Nabu/Mercury is one of the seven planetary deities of Harran (Green; Fihrist).'),
 ('ENT_HRN_SHAMASH_SUN','equated_with','ENT_MES_UTU_SHAMASH','high','The Harranian Sun-deity is the late continuation of Mesopotamian Utu/Shamash (ancient identification / cult continuity; Green).'),
 ('ENT_HRN_SHAMASH_SUN','equated_with','ENT_HELIOS','high','Greco-Roman sources and the Sabians themselves identified the Harranian Sun with Helios (interpretatio; Green).'),
 ('ENT_HRN_SHAMASH_SUN','aligned_with','ENT_AST_SUN_SPIRIT','medium','Functional alignment between the Harranian solar deity and the Picatrix Spirit of the Sun (al-Shams) in the shared Arabic planetary-magic milieu.'),
 ('ENT_HRN_SIN_MOON','reception_of','ENT_ARA_SIN_HARRAN','high','The Sabian Moon-cult of Harran is the direct continuation of the Aramean Sin of Harran into late antiquity (Green).'),
 ('ENT_HRN_SIN_MOON','equated_with','ENT_MES_NANNA_SIN','high','The Harranian Moon-god derives from and is identified with Mesopotamian Nanna/Sin (cult continuity; Green).'),
 ('ENT_HRN_SIN_MOON','equated_with','ENT_SELENE','high','Greco-Roman interpretatio identified the Harranian Moon with Selene (Green).'),
 ('ENT_HRN_SIN_MOON','aligned_with','ENT_AST_MOON_SPIRIT','medium','Functional alignment with the Picatrix Spirit of the Moon (al-Qamar) in the shared planetary-magic milieu.'),
 ('ENT_HRN_KRONOS_SATURN','equated_with','ENT_KRONOS','high','The Harranian Saturn-deity is explicitly identified with Greek Kronos (interpretatio; Fihrist, Green).'),
 ('ENT_HRN_KRONOS_SATURN','equated_with','ENT_MES_NINURTA','medium','Saturn in the Mesopotamian-Harranian astral scheme corresponds to Ninurta/Ninib (planetary identification; Green).'),
 ('ENT_HRN_KRONOS_SATURN','aligned_with','ENT_AST_SATURN_SPIRIT','medium','Functional alignment with the Picatrix Spirit of Saturn (Zuhal).'),
 ('ENT_HRN_ZEUS_JUPITER','equated_with','ENT_ZEUS','high','The Harranian Jupiter-deity is identified with Greek Zeus (interpretatio; Green).'),
 ('ENT_HRN_ZEUS_JUPITER','equated_with','ENT_MES_MARDUK','medium','Jupiter in the Mesopotamian-Harranian astral scheme corresponds to Marduk/Bel (planetary identification; Green).'),
 ('ENT_HRN_ZEUS_JUPITER','aligned_with','ENT_AST_JUPITER_SPIRIT','medium','Functional alignment with the Picatrix Spirit of Jupiter (al-Mushtari).'),
 ('ENT_HRN_ARES_MARS','equated_with','ENT_ARES','high','The Harranian Mars-deity is identified with Greek Ares (interpretatio; Green).'),
 ('ENT_HRN_ARES_MARS','equated_with','ENT_MES_NERGAL','high','Mars in the Mesopotamian-Harranian astral scheme is Nergal, god of war and the underworld (planetary identification; Green).'),
 ('ENT_HRN_ARES_MARS','aligned_with','ENT_AST_MARS_SPIRIT','medium','Functional alignment with the Picatrix Spirit of Mars (al-Mirrikh).'),
 ('ENT_HRN_APHRODITE_VENUS','equated_with','ENT_APHRODITE','high','The Harranian Venus-deity is identified with Greek Aphrodite (interpretatio; Green).'),
 ('ENT_HRN_APHRODITE_VENUS','equated_with','ENT_MES_INANNA_ISHTAR','high','Venus in the Mesopotamian-Harranian astral scheme is Inanna/Ishtar, the planet''s ancient owner (planetary identification; Green).'),
 ('ENT_HRN_APHRODITE_VENUS','aligned_with','ENT_AST_VENUS_SPIRIT','medium','Functional alignment with the Picatrix Spirit of Venus (al-Zuhra).'),
 ('ENT_HRN_HERMES_MERCURY','equated_with','ENT_HERMES','high','The Harranian Mercury-deity is identified with Greek Hermes (interpretatio; Green).'),
 ('ENT_HRN_HERMES_MERCURY','equated_with','ENT_MES_NABU','high','Mercury in the Mesopotamian-Harranian astral scheme is Nabu, scribal god of wisdom (planetary identification; Green).'),
 ('ENT_HRN_HERMES_MERCURY','aligned_with','ENT_AST_MERCURY_SPIRIT','medium','Functional alignment with the Picatrix Spirit of Mercury (Utarid).'),
 ('ENT_HRN_HERMES_TRISMEGISTUS','reception_of','ENT_HER_TRISMEGISTUS','high','The Harranian Sabians received Hermes Trismegistus of the Greco-Egyptian Hermetica as their founding prophet-sage (Green; Fihrist).'),
 ('ENT_HRN_HERMES_TRISMEGISTUS','equated_with','ENT_ISL_IDRIS','high','Harranian and Islamic sources identified the prophet Hermes with Qur''anic Idris (=Enoch), which secured the Sabians'' protected status under Islam (Green).'),
 ('ENT_HRN_AGATHODAIMON','reception_of','ENT_LAT_AGATHOS_DAIMON_HERMETIC','medium','The Harranian prophet-sage Agathodaimon is the Harranian reception of the pan-Hermetic Agathos Daimon (homonym; same figure received into the Sabian prophetic tradition; Green).'),
 ('ENT_HRN_AGATHODAIMON','member_of','ENT_HRN_PLANETARY_SEVEN','low','Agathodaimon is grouped with the Harranian prophetic/teaching tradition surrounding the planetary cult; weak roster linkage to the cult-hub (Fihrist tradition; Green).'),
 ('ENT_HRN_AGATHODAIMON','paired_with','ENT_HRN_HERMES_TRISMEGISTUS','medium','Agathodaimon is consistently paired with Hermes as a teacher-sage in the Hermetic and Harranian Sabian tradition (Green).'),
 ('ENT_HRN_AGATHODAIMON','reception_of','ENT_HER_POIMANDRES','low','Agathodaimon as Harranian revelatory ''Good Spirit'' parallels the Hermetic revealer-figure tradition exemplified by Poimandres (conceptual reception; Corpus Hermeticum).'),
 ('ENT_HRN_PLANETARY_ASCENT','associated_with','ENT_HRN_PLANETARY_SEVEN','high','The soul''s ascent passes through the spheres of the seven planetary deities, binding the doctrine to the cult-heptad (Green).'),
 ('ENT_HRN_PLANETARY_ASCENT','reception_of','ENT_HER_POIMANDRES','medium','The planetary-ascent schema follows the Poimandres account (CH I) of the soul shedding planetary qualities on its return to the divine; this is the Hermetic source of the Harranian doctrine (Green).'),
 ('ENT_HRN_TEMPLES','associated_with','ENT_HRN_PLANETARY_SEVEN','high','The planetary temples of Harran were each dedicated to one of the seven planetary deities, in distinctive geometric forms keyed to each planet (Fihrist; Green).'),
 ('ENT_HRN_TEMPLES','aligned_with','ENT_AST_PLANETARY_SPIRITS','low','The Harranian planetary-temple/talismanic scheme is part of the same Arabic astral-magic complex that the Picatrix''s seven planetary spirits draw on (shared milieu; Green).');
